                    <div className={`flex items-center gap-2 text-sm text-gray-400 transition-opacity ${step.enabled === false ? 'opacity-50' : ''}`}>
                        <span>{step.type === 'rest' ? 'מנוחה' : (step.isRepBased ? `${step.reps} חזרות` : `${step.duration} שניות`)}</span>
                        {step.tip && <span className="text-yellow-300/80 truncate max-w-[150px]">💡 {step.tip}</span>}
                    </div>
                </div>
                <button className="p-2 text-gray-400 hover:text-white shrink-0">
                    <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 transition-transform ${isExpanded ? 'rotate-180' : ''}`} viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
