const PlanEditor: React.FC<{
  plan?: WorkoutPlan;
  onSave: (plan: WorkoutPlan) => void;
  onCancel: () => void;
}> = ({ plan, onSave, onCancel }) => {
  const { settings } = useSettings();
  const [name, setName] = useState(plan?.name || '');
  const [executionMode, setExecutionMode] = useState<'linear' | 'circuit'>(plan?.executionMode || 'linear');
  const [steps, setSteps] = useState<WorkoutStep[]>(
      plan?.steps || [
          {
              id: `step_${Date.now()}`,
              name: 'Exercise 1',
              type: 'exercise',
              isRepBased: false,
              duration: settings.defaultExerciseDuration,
              reps: 10,
          },
      ]
  );

  const [draggedStepIndex, setDraggedStepIndex] = useState<number | null>(null);
  const [dragOverStepIndex, setDragOverStepIndex] = useState<number | null>(null);

  const addStep = (type: 'exercise' | 'rest') => {
      setSteps([
          ...steps,
          {
              id: `step_${Date.now()}`,
              name: type === 'exercise' ? `Exercise ${steps.length + 1}` : 'Rest',
              type,
              isRepBased: false,
              duration: type === 'exercise' ? settings.defaultExerciseDuration : settings.defaultRestDuration,
              reps: 10,
          },
      ]);
  };

  const updateStep = (index: number, updates: Partial<WorkoutStep>) => {
      const newSteps = [...steps];
      newSteps[index] = { ...newSteps[index], ...updates };
      setSteps(newSteps);
  };

  const removeStep = (index: number) => {
      setSteps(steps.filter((_, i) => i !== index));
  };

  const handleDragStart = (index: number) => {
      setDraggedStepIndex(index);
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
      e.preventDefault();
      setDragOverStepIndex(index);
  };

  const handleDrop = (index: number) => {
      if (draggedStepIndex === null || draggedStepIndex === index) return;
      const newSteps = [...steps];
      const [movedStep] = newSteps.splice(draggedStepIndex, 1);
      newSteps.splice(index, 0, movedStep);
      setSteps(newSteps);
      setDraggedStepIndex(null);
      setDragOverStepIndex(null);
  };

  const handleSave = () => {
      if (!name.trim()) return alert("Please enter a plan name.");
      if (steps.length === 0) return alert("Please add at least one step.");

      onSave({
          id: plan?.id || `plan_${Date.now()}`,
          name,
          executionMode,
          steps,
          isLocked: plan?.isLocked,
          isPinned: plan?.isPinned,
          version: 2,
      });
  };

  return (
      <div className="h-full flex flex-col">
          <div className="mb-4">
              <label className="block text-gray-400 text-sm mb-1">Plan Name</label>
              <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-gray-700 text-white p-2 rounded focus:outline-none focus:ring-2 ring-blue-500"
                  placeholder="e.g., Full Body Workout"
              />
          </div>

          <div className="mb-4 flex items-center gap-4">
              <label className="text-gray-400 text-sm">Mode:</label>
              <div className="flex bg-gray-700 rounded p-1">
                  <button
                      onClick={() => setExecutionMode('linear')}
                      className={`px-3 py-1 rounded text-sm transition-colors ${executionMode === 'linear' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
                  >
                      Linear
                  </button>
                  <button
                      onClick={() => setExecutionMode('circuit')}
                      className={`px-3 py-1 rounded text-sm transition-colors ${executionMode === 'circuit' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
                  >
                      Circuit
                  </button>
              </div>
          </div>

          <div className="flex-1 overflow-y-auto space-y-2 mb-4 pr-1">
              {steps.map((step, index) => (
                  <div
                      key={step.id}
                      draggable
                      onDragStart={() => handleDragStart(index)}
                      onDragOver={(e) => handleDragOver(e, index)}
                      onDrop={() => handleDrop(index)}
                      className={`bg-gray-700/50 p-3 rounded flex flex-col gap-2 border-l-4 ${step.type === 'exercise' ? 'border-blue-500' : 'border-gray-500'} ${dragOverStepIndex === index ? 'opacity-50' : ''}`}
                  >
                      <div className="flex justify-between items-center">
                          <span className="text-xs text-gray-500 uppercase font-bold tracking-wider cursor-move">Step {index + 1}</span>
                          <button onClick={() => removeStep(index)} className="text-gray-500 hover:text-red-400">
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                          </button>
                      </div>

                      <div className="flex gap-2">
                           <input
                              type="text"
                              value={step.name}
                              onChange={(e) => updateStep(index, { name: e.target.value })}
                              className="flex-1 bg-gray-600 text-white px-2 py-1 rounded text-sm focus:outline-none"
                              placeholder="Exercise Name"
                          />
                          <select 
                            value={step.type} 
                            onChange={(e) => updateStep(index, { type: e.target.value as 'exercise' | 'rest' })}
                            className="bg-gray-600 text-white text-sm rounded px-1 focus:outline-none"
                          >
                              <option value="exercise">Exercise</option>
                              <option value="rest">Rest</option>
                          </select>
                      </div>

                      <div className="flex items-center gap-3">
                          <label className="flex items-center cursor-pointer">
                              <input
                                  type="checkbox"
                                  checked={step.isRepBased}
                                  onChange={(e) => updateStep(index, { isRepBased: e.target.checked })}
                                  className="form-checkbox h-4 w-4 rounded bg-gray-600 border-gray-500 text-blue-500"
                              />
                              <span className="ml-2 text-sm text-gray-300">Reps</span>
                          </label>

                          {step.isRepBased ? (
                              <div className="flex items-center gap-2 ml-auto">
                                   <span className="text-sm text-gray-400">Count:</span>
                                   <input
                                      type="number"
                                      value={step.reps}
                                      onChange={(e) => updateStep(index, { reps: parseInt(e.target.value) || 0 })}
                                      className="w-16 bg-gray-600 text-white px-2 py-1 rounded text-sm text-center"
                                  />
                              </div>
                          ) : (
                               <div className="flex items-center gap-2 ml-auto">
                                   <span className="text-sm text-gray-400">Secs:</span>
                                   <input
                                      type="number"
                                      value={step.duration}
                                      onChange={(e) => updateStep(index, { duration: parseInt(e.target.value) || 0 })}
                                      className="w-16 bg-gray-600 text-white px-2 py-1 rounded text-sm text-center"
                                  />
                              </div>
                          )}
                      </div>
                      <input
                          type="text"
                          value={step.tip || ''}
                          onChange={(e) => updateStep(index, { tip: e.target.value })}
                          className="w-full bg-gray-600 text-gray-300 px-2 py-1 rounded text-xs focus:outline-none italic"
                          placeholder="Optional short tip (e.g. 'Keep back straight')"
                          maxLength={50}
                      />
                  </div>
              ))}
          </div>

          <div className="flex gap-2 mb-4">
              <button onClick={() => addStep('exercise')} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded text-sm">+ Exercise</button>
              <button onClick={() => addStep('rest')} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded text-sm">+ Rest</button>
          </div>

          <div className="flex gap-2 border-t border-gray-700 pt-4">
               <button onClick={onCancel} className="flex-1 py-2 bg-gray-600 hover:bg-gray-500 text-white rounded font-semibold">Cancel</button>
               <button onClick={handleSave} className="flex-1 py-2 bg-green-600 hover:bg-green-500 text-white rounded font-semibold">Save Plan</button>
          </div>
      </div>
  );
};

const AiPlanner: React.FC<{
    onBack: () => void;
    onImport: (plan: WorkoutPlan) => void;
}> = ({ onBack, onImport }) => {
    const { settings } = useSettings();
    const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string }[]>([
        { role: 'model', text: 'Hi! I can help you create a personalized workout plan. What are your goals today? (e.g., "30 min HIIT", "Upper body strength", "Yoga for beginners")' }
    ]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    const handleSend = async () => {
        if (!input.trim() || isLoading) return;
        const userMsg = input.trim();
        setInput('');
        setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
        setIsLoading(true);

        // Prepare history for API
        const historyForApi = messages.map(m => ({
            role: m.role,
            parts: [{ text: m.text }]
        }));

        const profileContext = settings.userProfile ? `
            User Profile:
            - Fitness Level: ${settings.userProfile.fitnessLevel}
            - Equipment: ${settings.userProfile.equipment?.filter(e => e.available).map(e => e.name).join(', ') || 'None'}
        ` : undefined;

        const responseText = await generateWorkoutPlan(historyForApi, userMsg, profileContext);

        setIsLoading(false);
        setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    };

    const extractJsonFromText = (text: string): WorkoutPlan | null => {
        const match = text.match(/```json\s*([\s\S]*?)\s*```/);
        if (match && match[1]) {
            try {
                return JSON.parse(match[1]);
            } catch (e) {
                console.error("Failed to parse JSON from AI response", e);
            }
        }
        return null;
    };

    return (
        <div className="h-full flex flex-col">
            <div className="flex items-center mb-4 border-b border-gray-700 pb-2">
                 <button onClick={onBack} className="mr-3 text-gray-400 hover:text-white">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                 </button>
                 <h3 className="text-xl font-bold text-white">AI Workout Planner</h3>
            </div>

            <div className="flex-1 overflow-y-auto space-y-4 mb-4 pr-2">
                {messages.map((msg, idx) => {
                     const plan = msg.role === 'model' ? extractJsonFromText(msg.text) : null;
                     // Clean text by removing the JSON block for display
                     const displayText = msg.role === 'model' ? msg.text.replace(/```json[\s\S]*```/, '').trim() : msg.text;

                     return (
                        <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                            <div className={`max-w-[85%] rounded-lg p-3 ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                                <p className="whitespace-pre-wrap text-sm">{displayText}</p>
                            </div>
                            {plan && (
                                <div className="mt-2 ml-1">
                                    <div className="bg-gray-800 border border-gray-600 rounded p-3 text-sm">
                                        <p className="font-bold text-white mb-1">{plan.name}</p>
                                        <p className="text-gray-400 mb-2">{plan.steps.length} steps</p>
                                        <button 
                                            onClick={() => onImport(plan)}
                                            className="w-full py-1.5 bg-green-600 hover:bg-green-500 text-white rounded font-semibold text-xs transition-colors"
                                        >
                                            Import This Plan
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>
                     );
                })}
                {isLoading && (
                    <div className="flex items-start">
                        <div className="bg-gray-700 rounded-lg p-3 text-gray-400 text-sm">
                            Thinking...
                        </div>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>

            <div className="flex gap-2">
                <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                    className="flex-1 bg-gray-700 text-white p-2 rounded focus:outline-none focus:ring-2 ring-blue-500"
                    placeholder="Describe your workout..."
                />
                <button 
                    onClick={handleSend}
                    disabled={isLoading || !input.trim()}
                    className="p-2 bg-blue-600 text-white rounded disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                </button>
            </div>
        </div>
    );
};


export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void }> = ({ isOpen, setIsOpen }) => {
    const { savePlan, deletePlan, importPlan, activeWorkout } = useWorkout();
    const { settings, updateSettings } = useSettings();
    const [view, setView] = useState<'list' | 'edit' | 'log' | 'ai' | 'info'>('list');
    const [selectedPlan, setSelectedPlan] = useState<WorkoutPlan | undefined>(undefined);
    const [isPinned, setIsPinned] = useState(false);

    // Exercise Info Modal State
    const [infoExerciseName, setInfoExerciseName] = useState<string | null>(null);

    const handleCreateNew = () => {
        setSelectedPlan(undefined);
        setView('edit');
    };

    const handleEdit = (plan: WorkoutPlan | string) => {
        // If string (ID), find plan? No, PlanList passes object usually.
        // But type def says `plan | string`. Let's handle it.
        if (typeof plan === 'string') {
           // Not implemented for ID lookup here, usually passed object
           return;
        }

        if (plan.id === '_warmup_') {
             // Special handling for warmup editing
             setSelectedPlan({
                 id: '_warmup_',
                 name: 'Warm-up Routine',
                 steps: settings.warmupSteps.length > 0 ? settings.warmupSteps : [{
                    id: `warmup_step_${Date.now()}`,
                    name: 'Jumping Jacks',
                    type: 'exercise',
                    isRepBased: false,
                    duration: 60,
                    reps: 0,
                    enabled: true
                 }],
                 executionMode: 'linear'
             });
             setView('edit');
        } else {
             setSelectedPlan(plan);
             setView('edit');
        }
    };

    const handleSavePlan = (plan: WorkoutPlan) => {
        if (plan.id === '_warmup_') {
            updateSettings({ warmupSteps: plan.steps });
        } else {
            savePlan(plan);
        }
        setView('list');
    };

    const handleImportAiPlan = (plan: WorkoutPlan) => {
        importPlan(plan, 'ai');
        // Stay in AI view or go to list? List seems better to show it's added.
        setView('list'); 
    };

    return (
        <>
            {/* Exercise Info Modal (Global to menu) */}
            <ExerciseInfoModal 
                exerciseName={infoExerciseName} 
                isVisible={!!infoExerciseName} 
                onClose={() => setInfoExerciseName(null)} 
            />

            {/* Backdrop */}
            {isOpen && (
                <div 
                    className="fixed inset-0 bg-black/60 z-40"
                    onClick={() => !isPinned && setIsOpen(false)}
                ></div>
            )}

            {/* Slide Panel */}
            <div 
                className={`fixed top-0 left-0 h-full w-full max-w-md bg-gray-800/90 backdrop-blur-md shadow-2xl z-50 transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}
            >
                <div className="p-6 h-full flex flex-col">
                     {/* Header */}
                     <div className="flex justify-between items-center mb-6">
                        <h2 className="text-2xl font-bold text-white">
                            {view === 'list' && 'Workouts'}
                            {view === 'edit' && (selectedPlan?.id === '_warmup_' ? 'Edit Warm-up' : (selectedPlan ? 'Edit Plan' : 'New Plan'))}
                            {view === 'log' && 'Log'}
                            {view === 'ai' && 'AI Planner'}
                            {view === 'info' && 'Stats'}
                        </h2>
                        <button onClick={() => setIsOpen(false)} className="p-2 rounded-full hover:bg-gray-700 text-gray-400">
                             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                        </button>
                    </div>

                    {/* Content */}
                    <div className="flex-1 overflow-hidden">
                        {view === 'list' && (
                            <PlanList 
                                onSelectPlan={handleEdit}
                                onCreateNew={handleCreateNew}
                                onInitiateDelete={(id) => {
                                    if(window.confirm("Delete this plan?")) deletePlan(id);
                                }}
                                onShowLog={() => setView('log')}
                                onInspectExercise={setInfoExerciseName}
                                onShowInfo={(plan) => { setSelectedPlan(plan); setView('info'); }}
                                isPinned={isPinned}
                                onTogglePin={() => setIsPinned(!isPinned)}
                                onOpenAiPlanner={() => setView('ai')}
                            />
                        )}

                        {view === 'edit' && (
                            <PlanEditor 
                                plan={selectedPlan}
                                onSave={handleSavePlan}
                                onCancel={() => setView('list')}
                            />
                        )}

                        {view === 'log' && (
                            <WorkoutLog onBack={() => setView('list')} />
                        )}

                        {view === 'ai' && (
                            <AiPlanner 
                                onBack={() => setView('list')}
                                onImport={handleImportAiPlan}
                            />
                        )}

                        {view === 'info' && selectedPlan && (
                            <WorkoutInfoModal 
                                plan={selectedPlan}
                                onClose={() => setView('list')}
                            />
                        )}
                    </div>
                </div>
            </div>
        </>
    );
};

import React, { useState, useEffect, useRef, useMemo, useLayoutEffect } from 'react';
import { useWorkout } from '../contexts/WorkoutContext';
import { WorkoutPlan, WorkoutStep } from '../types';
import { useSettings } from '../contexts/SettingsContext';
import { HoverNumberInput } from './HoverNumberInput';
import { getExerciseInfo, ExerciseInfo, prefetchExercises, generateWorkoutPlan } from '../services/geminiService';
import { WorkoutInfoModal } from './WorkoutInfoModal';
import { WorkoutLog } from './WorkoutLog';
import { getBaseExerciseName, generateCircuitSteps, getStepDisplayName } from '../utils/workout';
import { useAuth } from '../contexts/AuthContext';

const EDITOR_STORAGE_KEY = 'sportsClockPlanEditorDraft';

const ExerciseInfoModal: React.FC<{
  exerciseName: string | null;
  onClose: () => void;
  isVisible: boolean;
}> = ({ exerciseName, onClose, isVisible }) => {
  const [info, setInfo] = useState<ExerciseInfo | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'howto' | 'details'>('howto');
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const modalRef = useRef<HTMLDivElement>(null);
  const [activeVideoId, setActiveVideoId] = useState<string | null>(null);
  const [showLoadingMessage, setShowLoadingMessage] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);


  useEffect(() => {
    const fetchInfo = async () => {
      if (!exerciseName) return;
      setIsLoading(true);
      setError(null);
      try {
        const result = await getExerciseInfo(exerciseName);
        setInfo(result);
        setActiveVideoId(result.primaryVideoId);
        if (result.instructions.toLowerCase().includes("error") || result.instructions.toLowerCase().includes("failed") || result.instructions.includes("api key") || result.instructions.includes("מפתח api") || result.instructions.includes("שגיאה") || result.instructions.includes("מכסת שימוש")) {
            setError(result.instructions);
        }
      } catch (e) {
        const errorMessage = e instanceof Error ? e.message : "Failed to fetch or parse exercise information.";
        setError(errorMessage);
        console.error(e);
      } finally {
        setIsLoading(false);
      }
    };
    if (isVisible && exerciseName) {
        fetchInfo();
    }
  }, [exerciseName, isVisible]);

  // Bug Fix: Clear video URL when modal is hidden to stop playback
  useEffect(() => {
    if (isVisible && activeVideoId) {
      setVideoUrl(`https://www.youtube.com/embed/${activeVideoId}?autoplay=1`);
    } else {
      setVideoUrl(null);
    }
  }, [isVisible, activeVideoId]);

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (isLoading && isVisible) {
        // Only show the long loading message if loading takes more than 500ms
        timer = setTimeout(() => {
            setShowLoadingMessage(true);
        }, 500);
    } else {
        setShowLoadingMessage(false);
    }
    return () => clearTimeout(timer);
  }, [isLoading, isVisible]);

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    e.preventDefault();
    const startX = e.clientX - position.x;
    const startY = e.clientY - position.y;

    const handleMouseMove = (moveEvent: MouseEvent) => {
        setPosition({
            x: moveEvent.clientX - startX,
            y: moveEvent.clientY - startY,
        });
    };

    const handleMouseUp = () => {
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  const handleTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
    // e.preventDefault() might be too aggressive, let's see. It can prevent scrolling.
    const touch = e.touches[0];
    const startX = touch.clientX - position.x;
    const startY = touch.clientY - position.y;

    const handleTouchMove = (moveEvent: TouchEvent) => {
        const moveTouch = moveEvent.touches[0];
        setPosition({
            x: moveTouch.clientX - startX,
            y: moveTouch.clientY - startY,
        });
    };

    const handleTouchEnd = () => {
        document.removeEventListener('touchmove', handleTouchMove as any);
        document.removeEventListener('touchend', handleTouchEnd as any);
    };

    document.addEventListener('touchmove', handleTouchMove as any, { passive: false });
    document.addEventListener('touchend', handleTouchEnd as any);
  };

  const allVideoIds = useMemo(() => {
    if (!info) return [];
    const ids = [info.primaryVideoId, ...info.alternativeVideoIds].filter((id): id is string => !!id);
    return [...new Set(ids)]; // Remove duplicates
  }, [info]);

  const activeVideoIndex = useMemo(() => {
    if (!activeVideoId) return -1;
    return allVideoIds.indexOf(activeVideoId);
  }, [allVideoIds, activeVideoId]);

  const handleNextVideo = () => {
    if (allVideoIds.length === 0) return;
    const nextIndex = (activeVideoIndex + 1) % allVideoIds.length;
    setActiveVideoId(allVideoIds[nextIndex]);
  };

  const handlePrevVideo = () => {
    if (allVideoIds.length === 0) return;
    const prevIndex = (activeVideoIndex - 1 + allVideoIds.length) % allVideoIds.length;
    setActiveVideoId(allVideoIds[prevIndex]);
  };

  const isHebrew = useMemo(() => info?.language === 'he', [info]);

  const parsedInstructions = useMemo(() => {
    if (!info?.instructions) return [];

    const instructionsText = info.instructions.trim();
    let lines: string[];

    // First, try splitting by newline characters, which is the preferred format.
    if (instructionsText.includes('\n')) {
        lines = instructionsText.split('\n');
    } else {
        // Fallback: If no newlines, split by a pattern like "1. ", "2. ", etc.
        // The positive lookahead `(?=...)` splits *before* the number, keeping it for the next step.
        lines = instructionsText.split(/(?=\d+\.\s*)/);
    }

    return lines
      .map(line => line.trim().replace(/^\d+\.\s*/, '')) // remove the "1. " part
      .filter(line => line.length > 0);
  }, [info?.instructions]);

  const parsedTips = useMemo(() => {
    if (!info?.tips) return [];
    // This regex strips any leading number and dot (e.g., "1. ") to prevent "• 1. Tip" when rendered in a <ul>.
    return info.tips.map(tip => tip.trim().replace(/^\d+\.?\s*/, ''));
  }, [info?.tips]);

  const TabButton: React.FC<{
    label: string;
    isActive: boolean;
    onMouseDown: () => void;
  }> = ({ label, isActive, onMouseDown }) => (
    <button
      onMouseDown={onMouseDown}
      className={`px-4 py-2 text-sm font-semibold rounded-t-lg transition-colors focus:outline-none cursor-pointer ${
        isActive
          ? 'bg-gray-700 text-white'
          : 'text-gray-400 hover:bg-gray-700/50 hover:text-gray-200'
      }`}
    >
      {label}
    </button>
  );

  const handleSelectHowToTab = () => setActiveTab('howto');
  const handleSelectDetailsTab = () => setActiveTab('details');


  return (
    <div 
        className={`fixed inset-0 bg-black/70 z-[100] transition-opacity duration-300 ${isVisible ? 'opacity-100' : 'opacity-0 pointer-events-none'}`} 
        onClick={onClose} 
        aria-modal="true" 
        role="dialog"
    >
      <div 
        ref={modalRef}
        className={`bg-gray-800 rounded-lg shadow-xl w-full max-w-lg flex flex-col max-h-[90vh] absolute top-1/2 left-1/2 transition-all duration-300 ${isVisible ? 'scale-100 opacity-100' : 'scale-95 opacity-0'}`}
        style={{ transform: `translate(-50%, -50%) translate(${position.x}px, ${position.y}px)` }}
        onClick={e => e.stopPropagation()}
        dir={isHebrew ? 'rtl' : 'ltr'}
      >
        {/* Header */}
        <div 
            className="relative flex justify-center items-center p-4 border-b border-gray-700 cursor-move"
            onMouseDown={handleMouseDown}
            onTouchStart={handleTouchStart}
        >
          <h3 className="text-xl font-bold text-white break-all text-center mx-10">{exerciseName}</h3>
          <button onClick={onClose} className="absolute p-1 rounded-full hover:bg-gray-700 top-3 right-3 cursor-pointer">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        {/* Content */}
        <div className="p-4 flex-grow overflow-hidden flex flex-col">
          {isLoading ? (
            <div className="flex-grow flex items-center justify-center text-center" dir="rtl">
              {showLoadingMessage && <p className="text-gray-300 animate-pulse">מצאתי סרטונים, אני מנתח אותם כדי למצוא את הטוב ביותר. תהליך זה עשוי לקחת כדקה, תודה על הסבלנות.</p>}
            </div>
          ) : (
            <>
              {/* Tabs */}
              <div className="relative z-10 flex border-b border-gray-700 mb-4">
                <TabButton label={isHebrew ? "הדרכה" : "How-To"} isActive={activeTab === 'howto'} onMouseDown={handleSelectHowToTab} />
                <TabButton label={isHebrew ? "פרטים" : "Details"} isActive={activeTab === 'details'} onMouseDown={handleSelectDetailsTab} />
              </div>

              {/* Tab Content */}
              <div className="flex-grow overflow-y-scroll pr-2 min-h-0">
                {/* How-To Tab Pane */}
                <div className={`space-y-4 ${activeTab !== 'howto' ? 'hidden' : ''}`}>
                    {/* Video Embed */}
                    <div className="aspect-video bg-gray-900 rounded-lg overflow-hidden flex items-center justify-center">
                        {videoUrl ? (
                            <iframe
                                key={activeVideoId}
                                className="w-full h-full"
                                src={videoUrl}
                                title={`Video tutorial for ${exerciseName}`}
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        ) : (
                            <div className="text-gray-400 text-center p-4">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.55a1 1 0 01.55.89V14.11a1 1 0 01-1.55.89L15 14M5 18a2 2 0 01-2-2V8a2 2 0 012-2h8a2 2 0 012 2v8a2 2 0 01-2 2H5z" /></svg>
                                <p>{isHebrew ? "סרטון אינו זמין כרגע" : "Video not available at this time"}</p>
                            </div>
                        )}
                    </div>

                    {/* Video Navigation */}
                    {allVideoIds.length > 1 && (
                       <div className="flex justify-center items-center gap-4 mt-2">
                           <button onClick={handleNextVideo} className="p-2 rounded-full hover:bg-gray-700" title={isHebrew ? "הסרטון הבא" : "Next video"}>
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                           </button>
                           <button onClick={handlePrevVideo} className="p-2 rounded-full hover:bg-gray-700" title={isHebrew ? "הסרטון הקודם" : "Previous video"}>
                               <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                           </button>
                       </div>
                    )}

                    {/* Instructions List */}
                    <h4 className="font-semibold text-lg text-white mt-4">{isHebrew ? "הוראות" : "Instructions"}</h4>
                     {error ? (
                        <p className="text-yellow-400 bg-yellow-900/30 p-3 rounded-md whitespace-pre-wrap select-text">{error}</p>
                     ) : parsedInstructions.length > 1 ? (
                        <ol className="list-decimal list-inside space-y-2 text-gray-200 select-text">
                            {parsedInstructions.map((item, index) => <li key={index}>{item}</li>)}
                        </ol>
                     ) : parsedInstructions.length === 1 ? (
                        <p className="text-gray-200 whitespace-pre-wrap select-text">{parsedInstructions[0]}</p>
                     ) : (
                        <p className="text-gray-400">{isHebrew ? "לא נמצאו הוראות." : "No instructions found."}</p>
                     )}
                </div>

                {/* Details Tab Pane */}
                <div className={`space-y-6 ${activeTab !== 'details' ? 'hidden' : ''}`}>
                    {info && info.tips && info.tips.length > 0 && (
                      <div>
                        <h4 className="font-semibold text-lg text-white mb-2">{isHebrew ? "דגשים" : "Tips"}</h4>
                        <ul className="list-disc list-inside space-y-1 text-gray-300 select-text">
                          {parsedTips.map((tip, index) => <li key={index}>{tip}</li>)}
                        </ul>
                      </div>
                    )}
                    {info && info.generalInfo && (
                      <div>
                        <h4 className="font-semibold text-lg text-white mb-2">{isHebrew ? "מידע כללי" : "General Info"}</h4>
                        <p className="text-gray-300 whitespace-pre-wrap select-text">{info.generalInfo}</p>
                      </div>
                    )}
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

const ShareModal: React.FC<{
  plan: WorkoutPlan;
  onClose: () => void;
}> = ({ plan, onClose }) => {
    const [copyButtonText, setCopyButtonText] = useState('Copy Link');

    const shareLink = useMemo(() => {
        try {
            const planJson = JSON.stringify(plan);
            const encoder = new TextEncoder();
            const data = encoder.encode(planJson);
            const binaryString = Array.from(data, byte => String.fromCharCode(byte)).join('');
            const base64Data = btoa(binaryString);

            const url = new URL(window.location.href);
            url.hash = `import=${base64Data}`;
            url.search = '';
            return url.toString();
        } catch (error) {
            console.error("Failed to create share link:", error);
            return '';
        }
    }, [plan]);

