  );
};

const PlanEditor: React.FC<{
  plan?: WorkoutPlan;
  onSave: (plan: WorkoutPlan) => void;
  onCancel: () => void;
}> = ({ plan, onSave, onCancel }) => {
  const { settings } = useSettings();
  const [name, setName] = useState(plan?.name || '');
  const [executionMode, setExecutionMode] = useState<'linear' | 'circuit'>(plan?.executionMode || 'linear');
  const [steps, setSteps] = useState<WorkoutStep[]>(
      plan?.steps || [
          {
              id: `step_${Date.now()}`,
              name: 'Exercise 1',
              type: 'exercise',
              isRepBased: false,
              duration: settings.defaultExerciseDuration,
              reps: 10,
          },
      ]
  );

  const [draggedStepIndex, setDraggedStepIndex] = useState<number | null>(null);
  const [dragOverStepIndex, setDragOverStepIndex] = useState<number | null>(null);

  const addStep = (type: 'exercise' | 'rest') => {
      setSteps([
          ...steps,
          {
              id: `step_${Date.now()}`,
              name: type === 'exercise' ? `Exercise ${steps.length + 1}` : 'Rest',
              type,
              isRepBased: false,
              duration: type === 'exercise' ? settings.defaultExerciseDuration : settings.defaultRestDuration,
              reps: 10,
          },
      ]);
  };

  const updateStep = (index: number, updates: Partial<WorkoutStep>) => {
      const newSteps = [...steps];
      newSteps[index] = { ...newSteps[index], ...updates };
      setSteps(newSteps);
  };

  const removeStep = (index: number) => {
      setSteps(steps.filter((_, i) => i !== index));
  };

  const handleDragStart = (index: number) => {
      setDraggedStepIndex(index);
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
      e.preventDefault();
      setDragOverStepIndex(index);
  };

  const handleDrop = (index: number) => {
      if (draggedStepIndex === null || draggedStepIndex === index) return;
      const newSteps = [...steps];
      const [movedStep] = newSteps.splice(draggedStepIndex, 1);
      newSteps.splice(index, 0, movedStep);
      setSteps(newSteps);
      setDraggedStepIndex(null);
      setDragOverStepIndex(null);
  };

  const handleSave = () => {
      if (!name.trim()) return alert("Please enter a plan name.");
      if (steps.length === 0) return alert("Please add at least one step.");

      onSave({
          id: plan?.id || `plan_${Date.now()}`,
          name,
          executionMode,
          steps,
          isLocked: plan?.isLocked,
          isPinned: plan?.isPinned,
          version: 2,
      });
  };

  return (
      <div className="h-full flex flex-col">
          <div className="mb-4">
              <label className="block text-gray-400 text-sm mb-1">Plan Name</label>
              <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-gray-700 text-white p-2 rounded focus:outline-none focus:ring-2 ring-blue-500"
                  placeholder="e.g., Full Body Workout"
              />
          </div>

          <div className="mb-4 flex items-center gap-4">
              <label className="text-gray-400 text-sm">Mode:</label>
              <div className="flex bg-gray-700 rounded p-1">
                  <button
                      onClick={() => setExecutionMode('linear')}
                      className={`px-3 py-1 rounded text-sm transition-colors ${executionMode === 'linear' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
                  >
                      Linear
                  </button>
                  <button
                      onClick={() => setExecutionMode('circuit')}
                      className={`px-3 py-1 rounded text-sm transition-colors ${executionMode === 'circuit' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
                  >
                      Circuit
                  </button>
              </div>
          </div>

          <div className="flex-1 overflow-y-auto space-y-2 mb-4 pr-1">
              {steps.map((step, index) => (
                  <div
                      key={step.id}
                      draggable
                      onDragStart={() => handleDragStart(index)}
                      onDragOver={(e) => handleDragOver(e, index)}
                      onDrop={() => handleDrop(index)}
                      className={`bg-gray-700/50 p-3 rounded flex flex-col gap-2 border-l-4 ${step.type === 'exercise' ? 'border-blue-500' : 'border-gray-500'} ${dragOverStepIndex === index ? 'opacity-50' : ''}`}
                  >
                      <div className="flex justify-between items-center">
                          <span className="text-xs text-gray-500 uppercase font-bold tracking-wider cursor-move">Step {index + 1}</span>
                          <button onClick={() => removeStep(index)} className="text-gray-500 hover:text-red-400">
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                          </button>
                      </div>

                      <div className="flex gap-2">
                           <input
                              type="text"
                              value={step.name}
                              onChange={(e) => updateStep(index, { name: e.target.value })}
                              className="flex-1 bg-gray-600 text-white px-2 py-1 rounded text-sm focus:outline-none"
                              placeholder="Exercise Name"
                          />
                          <select 
                            value={step.type} 
                            onChange={(e) => updateStep(index, { type: e.target.value as 'exercise' | 'rest' })}
                            className="bg-gray-600 text-white text-sm rounded px-1 focus:outline-none"
                          >
                              <option value="exercise">Exercise</option>
                              <option value="rest">Rest</option>
                          </select>
                      </div>

                      <div className="flex items-center gap-3">
                          <label className="flex items-center cursor-pointer">
                              <input
                                  type="checkbox"
                                  checked={step.isRepBased}
                                  onChange={(e) => updateStep(index, { isRepBased: e.target.checked })}
                                  className="form-checkbox h-4 w-4 rounded bg-gray-600 border-gray-500 text-blue-500"
                              />
                              <span className="ml-2 text-sm text-gray-300">Reps</span>
                          </label>

                          {step.isRepBased ? (
                              <div className="flex items-center gap-2 ml-auto">
                                   <span className="text-sm text-gray-400">Count:</span>
                                   <input
                                      type="number"
                                      value={step.reps}
                                      onChange={(e) => updateStep(index, { reps: parseInt(e.target.value) || 0 })}
                                      className="w-16 bg-gray-600 text-white px-2 py-1 rounded text-sm text-center"
                                  />
                              </div>
                          ) : (
                               <div className="flex items-center gap-2 ml-auto">
                                   <span className="text-sm text-gray-400">Secs:</span>
                                   <input
                                      type="number"
                                      value={step.duration}
                                      onChange={(e) => updateStep(index, { duration: parseInt(e.target.value) || 0 })}
                                      className="w-16 bg-gray-600 text-white px-2 py-1 rounded text-sm text-center"
                                  />
                              </div>
                          )}
                      </div>
                      <input
                          type="text"
                          value={step.tip || ''}
                          onChange={(e) => updateStep(index, { tip: e.target.value })}
                          className="w-full bg-gray-600 text-gray-300 px-2 py-1 rounded text-xs focus:outline-none italic"
                          placeholder="Optional short tip (e.g. 'Keep back straight')"
                          maxLength={50}
                      />
                  </div>
              ))}
          </div>

          <div className="flex gap-2 mb-4">
              <button onClick={() => addStep('exercise')} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded text-sm">+ Exercise</button>
              <button onClick={() => addStep('rest')} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded text-sm">+ Rest</button>
          </div>

          <div className="flex gap-2 border-t border-gray-700 pt-4">
               <button onClick={onCancel} className="flex-1 py-2 bg-gray-600 hover:bg-gray-500 text-white rounded font-semibold">Cancel</button>
               <button onClick={handleSave} className="flex-1 py-2 bg-green-600 hover:bg-green-500 text-white rounded font-semibold">Save Plan</button>
          </div>
      </div>
  );
};

const AiPlanner: React.FC<{
    onBack: () => void;
    onImport: (plan: WorkoutPlan) => void;
}> = ({ onBack, onImport }) => {
    const { settings } = useSettings();
    const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string }[]>([
        { role: 'model', text: 'Hi! I can help you create a personalized workout plan. What are your goals today? (e.g., "30 min HIIT", "Upper body strength", "Yoga for beginners")' }
    ]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    const handleSend = async () => {
        if (!input.trim() || isLoading) return;
        const userMsg = input.trim();
        setInput('');
        setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
        setIsLoading(true);

        // Prepare history for API
        const historyForApi = messages.map(m => ({
            role: m.role,
            parts: [{ text: m.text }]
        }));

        const profileContext = settings.userProfile ? `
            User Profile:
            - Fitness Level: ${settings.userProfile.fitnessLevel}
            - Equipment: ${settings.userProfile.equipment?.filter(e => e.available).map(e => e.name).join(', ') || 'None'}
        ` : undefined;

        const responseText = await generateWorkoutPlan(historyForApi, userMsg, profileContext);

        setIsLoading(false);
        setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    };

    const extractJsonFromText = (text: string): WorkoutPlan | null => {
        const match = text.match(/```json\s*([\s\S]*?)\s*```/);
        if (match && match[1]) {
            try {
                return JSON.parse(match[1]);
            } catch (e) {
                console.error("Failed to parse JSON from AI response", e);
            }
        }
        return null;
    };

    return (
        <div className="h-full flex flex-col">
            <div className="flex items-center mb-4 border-b border-gray-700 pb-2">
                 <button onClick={onBack} className="mr-3 text-gray-400 hover:text-white">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                 </button>
                 <h3 className="text-xl font-bold text-white">AI Workout Planner</h3>
            </div>

            <div className="flex-1 overflow-y-auto space-y-4 mb-4 pr-2">
                {messages.map((msg, idx) => {
                     const plan = msg.role === 'model' ? extractJsonFromText(msg.text) : null;
                     // Clean text by removing the JSON block for display
                     const displayText = msg.role === 'model' ? msg.text.replace(/```json[\s\S]*```/, '').trim() : msg.text;

                     return (
                        <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                            <div className={`max-w-[85%] rounded-lg p-3 ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                                <p className="whitespace-pre-wrap text-sm">{displayText}</p>
                            </div>
                            {plan && (
                                <div className="mt-2 ml-1">
                                    <div className="bg-gray-800 border border-gray-600 rounded p-3 text-sm">
                                        <p className="font-bold text-white mb-1">{plan.name}</p>
                                        <p className="text-gray-400 mb-2">{plan.steps.length} steps</p>
                                        <button 
                                            onClick={() => onImport(plan)}
                                            className="w-full py-1.5 bg-green-600 hover:bg-green-500 text-white rounded font-semibold text-xs transition-colors"
                                        >
                                            Import This Plan
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>
                     );
                })}
                {isLoading && (
                    <div className="flex items-start">
                        <div className="bg-gray-700 rounded-lg p-3 text-gray-400 text-sm">
                            Thinking...
                        </div>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>

            <div className="flex gap-2">
                <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                    className="flex-1 bg-gray-700 text-white p-2 rounded focus:outline-none focus:ring-2 ring-blue-500"
                    placeholder="Describe your workout..."
                />
                <button 
                    onClick={handleSend}
                    disabled={isLoading || !input.trim()}
                    className="p-2 bg-blue-600 text-white rounded disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                </button>
            </div>
        </div>
    );
};


