                className={`fixed top-0 left-0 h-full w-full max-w-md bg-gray-800/90 backdrop-blur-md shadow-2xl z-50 transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}
