    <content><![CDATA[import React, { Component, ErrorInfo, ReactNode } from 'react';
import { useLogger } from '../contexts/LoggingContext';

const CRASH_FLAG_KEY = 'app_crash_detected';

interface Props {
    children?: ReactNode;
}

interface State {
    hasError: boolean;
    error?: Error;
    info?: ErrorInfo;
}

/**
 * Internal class-based
 */
class ErrorBoundaryInternal extends Component<Props, State> {
    constructor(props: Props) {
        super(props);
        this.state = { hasError: false };
    }

    static getDerivedStateFromError(error: Error): State {
        return { hasError: true, error };
    }

    componentDidCatch(error: Error, info: ErrorInfo): void {
        const { logError } = useLogger();

        try {
            if (!localStorage.getItem(CRASH_FLAG_KEY)) {
                logError(error, info.componentStack || '');
                localStorage.setItem(CRASH_FLAG_KEY, 'true');
            }
        } catch (storageError) {
            logError(storageError as Error, 'LocalStorage Error');
            console.error('Local Storage Error:', storageError);
        }
    }

    render(): ReactNode {
        if (this.state.hasError) {
            return (
                <div className="flex flex-col items-center justify-center h-screen bg-gray-100 text-gray-800">
                    <h1 className="text-2xl font-semibold mb-4 text-red-600">
                        אופס! משהו השתבש.
                    </h1>
                    <p className="text-center mb-8 max-w-md">
