          <h3 className="text-xl font-bold text-white mx-4 text-center flex-1">{exerciseName}</h3>
          <button onClick={onClose} className="p-1 rounded-full hover:bg-gray-700 text-white">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="p-4 flex-grow overflow-y-auto">
          {isLoading ? (
            <div className="flex justify-center p-8"><div className="animate-spin h-8 w-8 border-4 border-blue-500 rounded-full border-t-transparent"></div></div>
          ) : (
            <>
              <div className="flex border-b border-gray-700 mb-4">
                <button onClick={() => setActiveTab('howto')} className={`px-4 py-2 ${activeTab === 'howto' ? 'border-b-2 border-blue-500 text-white' : 'text-gray-400'}`}>How-To</button>
