              </div>

              {activeTab === 'howto' && (
                <div className="space-y-4">
                    <div className="aspect-video bg-gray-900 rounded overflow-hidden">
                        {videoUrl ? (
                            <iframe className="w-full h-full" src={videoUrl} allow="autoplay; encrypted-media" allowFullScreen title="Video"></iframe>
