const PlanEditor: React.FC<{
  initialPlan?: WorkoutPlan;
  onSave: (plan: WorkoutPlan) => void;
  onCancel: () => void;
}> = ({ initialPlan, onSave, onCancel }) => {
  const { settings } = useSettings();
  const [name, setName] = useState(initialPlan?.name || '');
  const [steps, setSteps] = useState<WorkoutStep[]>(initialPlan?.steps || []);
  const [executionMode, setExecutionMode] = useState<'linear' | 'circuit'>(initialPlan?.executionMode || 'linear');

  const handleAddStep = (type: 'exercise' | 'rest') => {
    setSteps([...steps, {
      id: Date.now().toString(),
      name: type === 'exercise' ? 'New Exercise' : 'Rest',
      type,
      isRepBased: false,
      duration: type === 'exercise' ? settings.defaultExerciseDuration : settings.defaultRestDuration,
      reps: 10,
    }]);
  };

  const updateStep = (id: string, updates: Partial<WorkoutStep>) => {
    setSteps(steps.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const removeStep = (index: number) => {
    setSteps(steps.filter((_, i) => i !== index));
  };

  const moveStep = (index: number, direction: -1 | 1) => {
      if ((direction === -1 && index === 0) || (direction === 1 && index === steps.length - 1)) return;
      const newSteps = [...steps];
      const [moved] = newSteps.splice(index, 1);
      newSteps.splice(index + direction, 0, moved);
      setSteps(newSteps);
  };

  const handleSave = () => {
    if (!name.trim() || steps.length === 0) {
        alert("Please provide a name and at least one step.");
        return;
    }
    onSave({
        id: initialPlan?.id || Date.now().toString(),
        name,
        steps,
        executionMode,
        isPinned: initialPlan?.isPinned,
        isLocked: initialPlan?.isLocked,
        isSmartPlan: initialPlan?.isSmartPlan
    });
  };

  return (
    <div className="flex flex-col h-full">
        <div className="flex justify-between items-center mb-4 shrink-0">
            <h3 className="text-xl font-bold text-white">{initialPlan ? 'Edit Plan' : 'New Plan'}</h3>
            <button onClick={onCancel} className="text-gray-400 hover:text-white">Cancel</button>
        </div>
        <input 
            className="bg-gray-700 text-white p-2 rounded mb-4 w-full" 
            value={name} 
            onChange={e => setName(e.target.value)} 
            placeholder="Plan Name" 
        />
        <div className="flex bg-gray-700 rounded p-1 mb-4 shrink-0">
            <button onClick={() => setExecutionMode('linear')} className={`flex-1 py-1 rounded ${executionMode === 'linear' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>Linear</button>
            <button onClick={() => setExecutionMode('circuit')} className={`flex-1 py-1 rounded ${executionMode === 'circuit' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>Circuit</button>
        </div>
        <div className="flex-1 overflow-y-auto space-y-2 pr-1 mb-4">
            {steps.map((step, index) => (
                <div key={step.id} className="bg-gray-700/50 p-2 rounded flex flex-col gap-2 border-l-2 border-gray-600">
                    <div className="flex gap-2">
                        <input value={step.name} onChange={e => updateStep(step.id, { name: e.target.value })} className="bg-transparent text-white font-semibold flex-1 outline-none border-b border-transparent focus:border-blue-500" />
                        <button onClick={() => moveStep(index, -1)} disabled={index===0} className="text-gray-400 hover:text-white">↑</button>
                        <button onClick={() => moveStep(index, 1)} disabled={index===steps.length-1} className="text-gray-400 hover:text-white">↓</button>
                        <button onClick={() => removeStep(index)} className="text-red-400 hover:text-red-300">×</button>
                    </div>
                    <div className="flex items-center gap-3 text-xs text-gray-300">
                        <label className="flex items-center gap-1"><input type="checkbox" checked={step.type === 'rest'} onChange={e => updateStep(step.id, { type: e.target.checked ? 'rest' : 'exercise' })} /> Rest</label>
                        {step.type === 'exercise' && (
                            <label className="flex items-center gap-1"><input type="checkbox" checked={step.isRepBased} onChange={e => updateStep(step.id, { isRepBased: e.target.checked })} /> Reps</label>
                        )}
                        <div className="ml-auto flex items-center gap-1">
                            {step.isRepBased ? (
                                <><span>Count:</span><input type="number" value={step.reps} onChange={e => updateStep(step.id, { reps: parseInt(e.target.value)||0 })} className="w-12 bg-gray-600 text-center rounded" /></>
                            ) : (
                                <><span>Secs:</span><input type="number" value={step.duration} onChange={e => updateStep(step.id, { duration: parseInt(e.target.value)||0 })} className="w-12 bg-gray-600 text-center rounded" /></>
                            )}
                        </div>
                    </div>
                </div>
            ))}
        </div>
        <div className="flex gap-2 mb-4 shrink-0">
            <button onClick={() => handleAddStep('exercise')} className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-2 rounded">+ Exercise</button>
            <button onClick={() => handleAddStep('rest')} className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-2 rounded">+ Rest</button>
        </div>
        <button onClick={handleSave} className="w-full bg-green-600 hover:bg-green-500 text-white py-3 rounded font-bold shrink-0">Save Plan</button>
    </div>
  );
};

// --- AI Planner ---

const AiPlanner: React.FC<{ onClose: () => void; onImport: (plan: WorkoutPlan) => void; }> = ({ onClose, onImport }) => {
    const [input, setInput] = useState('');
    const [messages, setMessages] = useState<{role:string, text:string}[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const { settings } = useSettings();

    const handleSend = async () => {
        if (!input.trim()) return;
        const msg = input;
        setInput('');
        setMessages(prev => [...prev, { role: 'user', text: msg }]);
        setIsLoading(true);

        try {
            const history = messages.map(m => ({ role: m.role as 'user'|'model', parts: [{ text: m.text }] }));
            const profile = settings.userProfile ? `Fitness: ${settings.userProfile.fitnessLevel}, Equip: ${settings.userProfile.equipment?.filter(e=>e.available).map(e=>e.name).join(',')}` : undefined;
            const response = await generateWorkoutPlan(history, msg, profile);

            const jsonMatch = response.match(/```json\s*([\s\S]*?)\s*```/);
            if (jsonMatch) {
                const plan = JSON.parse(jsonMatch[1]);
                onImport({ ...plan, id: `ai_${Date.now()}`, isSmartPlan: true, steps: plan.steps.map((s:any,i:number) => ({...s, id: `s_${i}`})) });
                onClose();
            } else {
                setMessages(prev => [...prev, { role: 'model', text: response }]);
            }
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', text: "Error generating plan." }]);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="flex flex-col h-full bg-gray-900 rounded-lg">
            <div className="flex justify-between items-center p-4 border-b border-gray-700">
                <h3 className="font-bold text-white">AI Coach</h3>
                <button onClick={onClose}>✕</button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-3">
                {messages.map((m, i) => (
                    <div key={i} className={`p-3 rounded-lg ${m.role==='user'?'bg-blue-600 ml-8':'bg-gray-700 mr-8'}`}>{m.text}</div>
                ))}
                {isLoading && <div className="text-gray-400">Thinking...</div>}
            </div>
            <div className="p-4 border-t border-gray-700 flex gap-2">
                <input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleSend()} className="flex-1 bg-gray-800 rounded p-2 text-white" placeholder="Describe your workout..." />
                <button onClick={handleSend} className="bg-purple-600 px-4 rounded text-white">→</button>
            </div>
        </div>
    );
};

