export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void }> = ({ isOpen, setIsOpen }) => {
  const { plans, savePlan, deletePlan, importPlan } = useWorkout();
  const { updateSettings, settings } = useSettings();
  const [view, setView] = useState<'list' | 'editor' | 'ai' | 'log' | 'info'>('list');
  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [isPinned, setIsPinned] = useState(false);
  const [exerciseInfoName, setExerciseInfoName] = useState<string | null>(null);

  // Auto-close logic
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => {
      if (isOpen && !isPinned && view === 'list') {
          timerRef.current = setTimeout(() => setIsOpen(false), 10000);
      }
      return () => { if (timerRef.current) clearTimeout(timerRef.current); };
  }, [isOpen, isPinned, view]);

  const handleCreateNew = () => { setEditingPlanId(null); setView('editor'); };
  const handleEdit = (plan: WorkoutPlan | string) => {
      if (typeof plan === 'string' && plan === '_warmup_') {
          setEditingPlanId('_warmup_');
      } else if (typeof plan !== 'string') {
          setEditingPlanId(plan.id);
      }
      setView('editor');
  };

  const handleSavePlan = (plan: WorkoutPlan) => {
      if (editingPlanId === '_warmup_') {
          updateSettings({ warmupSteps: plan.steps });
      } else {
          savePlan(plan);
      }
      setView('list');
  };

  const currentEditingPlan = useMemo(() => {
      if (editingPlanId === '_warmup_') {
          return { id: '_warmup_', name: 'Warm-up', steps: settings.warmupSteps, executionMode: 'linear' as const };
      }
      return plans.find(p => p.id === editingPlanId);
  }, [editingPlanId, plans, settings.warmupSteps]);

  return (
    <>
      {/* Exercise Info Modal (Global) */}
      <ExerciseInfoModal exerciseName={exerciseInfoName} isVisible={!!exerciseInfoName} onClose={() => setExerciseInfoName(null)} />

      {/* The Menu Button - Must be outside the drawer to be visible when closed */}
      <div className="absolute top-4 left-4 menu-container group z-[60]">
        <button
            onClick={() => setIsOpen(true)}
            className={`w-12 h-12 flex items-center justify-center rounded-full bg-gray-500/20 text-gray-400 hover:bg-gray-500/30 transition-opacity duration-1000 focus:outline-none ${isOpen ? 'opacity-0 pointer-events-none' : 'opacity-0 group-hover:opacity-100'}`}
            aria-label="Open workout menu"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
        </button>
      </div>

      {/* Backdrop */}
      {isOpen && (
        <div className="fixed inset-0 bg-black/60 z-40" onClick={() => !isPinned && setIsOpen(false)}></div>
      )}

      {/* Drawer */}
      <div className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-800/95 backdrop-blur-md shadow-2xl z-50 transform transition-transform duration-300 ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}
           onMouseEnter={() => timerRef.current && clearTimeout(timerRef.current)}>
        <div className="h-full flex flex-col p-4 overflow-hidden">
            {/* Header */}
            <div className="flex justify-between items-center mb-4 shrink-0">
                <h2 className="text-xl font-bold text-white">
                    {view === 'list' ? 'Workouts' : view === 'editor' ? 'Editor' : view === 'ai' ? 'AI Planner' : 'Log'}
                </h2>
                <div className="flex gap-2">
                    <button onClick={() => setIsPinned(!isPinned)} className={`p-1 rounded ${isPinned ? 'text-blue-400' : 'text-gray-500'}`}>📌</button>
                    <button onClick={() => setIsOpen(false)} className="p-1 text-gray-400 hover:text-white">✕</button>
                </div>
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-hidden relative">
                {view === 'list' && (
                    <div className="h-full overflow-y-auto">
                        <PlanList 
                            onSelectPlan={handleEdit} 
                            onCreateNew={handleCreateNew} 
                            onInitiateDelete={(id) => window.confirm('Delete?') && deletePlan(id)}
                            onShowLog={() => setView('log')}
                            onOpenAiPlanner={() => setView('ai')}
                        />
                    </div>
                )}
                {view === 'editor' && (
                    <PlanEditor 
                        initialPlan={currentEditingPlan} 
                        onSave={handleSavePlan} 
                        onCancel={() => setView('list')} 
                    />
                )}
                {view === 'ai' && (
                    <AiPlanner 
                        onClose={() => setView('list')} 
                        onImport={(p) => { importPlan(p, 'ai'); setView('list'); }} 
                    />
                )}
                {view === 'log' && (
                    <WorkoutLog onBack={() => setView('list')} />
                )}
            </div>
        </div>
      </div>
    </>
  );
};

