    const handleSavePlan = (plan: WorkoutPlan) => {
        if (plan.id === '_warmup_') {
            updateSettings({ warmupSteps: plan.steps });
        } else {
            savePlan(plan);
        }
        setView('list');
        setEditingPlan(null);
    };

    const handleClose = () => {
        setIsOpen(false);
        setIsPinned(false);
    };

    return (
        <>
            {isOpen && <div className="fixed inset-0 bg-black/50 z-40" onClick={() => !isPinned && handleClose()}></div>}

