export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void; }> = ({ isOpen, setIsOpen }) => {
  const { plans, savePlan, deletePlan, activeWorkout, startWorkout, importPlan, reorderPlans, recentlyImportedPlanId, isSyncing, forceSync } = useWorkout();
  const [isEditing, setIsEditing] = useState(false);
  const [editingPlan, setEditingPlan] = useState<WorkoutPlan | undefined>(undefined);
  const [showLog, setShowLog] = useState(false);
  const [showAI, setShowAI] = useState(false);

  // Drag and Drop state
  const [draggedItemIndex, setDraggedItemIndex] = useState<number | null>(null);
  const [dragOverItemIndex, setDragOverItemIndex] = useState<number | null>(null);
  const itemRefs = useRef<(HTMLDivElement | null)[]>([]);

  // Selection state for multiple workout start
  const [selectedPlanIds, setSelectedPlanIds] = useState<string[]>([]);

  const handleDragStart = (e: React.DragEvent, index: number) => {
    setDraggedItemIndex(index);
    e.dataTransfer.effectAllowed = 'move';
    // Create a ghost image if needed, or rely on browser default
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault(); // Necessary to allow dropping
    if (draggedItemIndex === null || draggedItemIndex === index) return;
    setDragOverItemIndex(index);
  };

  const handleDrop = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedItemIndex === null || draggedItemIndex === index) return;

    const newPlans = [...plans];
    const [draggedItem] = newPlans.splice(draggedItemIndex, 1);
    newPlans.splice(index, 0, draggedItem);

    reorderPlans(newPlans);
    setDraggedItemIndex(null);
    setDragOverItemIndex(null);
  };

  const handleDragEnd = () => {
    setDraggedItemIndex(null);
    setDragOverItemIndex(null);
  };

  const handleDragLeave = () => {
      // Optional: Logic to clear dragOverItemIndex if leaving the container
  };

  const handleCreatePlan = () => {
    setEditingPlan(undefined);
    setIsEditing(true);
    setShowAI(false);
  };

  const handleEditPlan = (plan: WorkoutPlan) => {
      setEditingPlan(plan);
      setIsEditing(true);
      setShowAI(false);
  };

  const handleSavePlan = (plan: WorkoutPlan) => {
    savePlan(plan);
    setIsEditing(false);
    setEditingPlan(undefined);
  };

  const toggleSelection = (planId: string) => {
    setSelectedPlanIds(prev => 
        prev.includes(planId) ? prev.filter(id => id !== planId) : [...prev, planId]
    );
  };

  const startSelected = () => {
      if (selectedPlanIds.length > 0) {
          startWorkout(selectedPlanIds);
          setSelectedPlanIds([]);
          setIsOpen(false);
      }
  };

  return (
    <div 
      className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-800/95 backdrop-blur-md shadow-2xl z-50 transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}
    >
      {/* Drawer Header or Content based on state */}
      <div className="h-full flex flex-col">
          {showLog ? (
              <WorkoutLog onBack={() => setShowLog(false)} />
          ) : isEditing ? (
              <PlanEditor 
                  initialPlan={editingPlan} 
                  onSave={handleSavePlan} 
                  onCancel={() => { setIsEditing(false); setEditingPlan(undefined); }} 
                  isAI={showAI}
              />
          ) : (
              <div className="flex flex-col h-full p-4 overflow-hidden">
                  <div className="flex justify-between items-center mb-4">
                      <h2 className="text-2xl font-bold text-white">Workouts</h2>
                      <button onClick={() => setIsOpen(false)} className="p-2 text-gray-400 hover:text-white">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                      </button>
                  </div>

                  <div className="flex gap-2 mb-4">
                      <button onClick={handleCreatePlan} className="flex-1 py-2 bg-blue-600 hover:bg-blue-700 rounded text-white font-semibold text-sm">New Plan</button>
                      <button onClick={() => setShowLog(true)} className="flex-1 py-2 bg-gray-600 hover:bg-gray-700 rounded text-white font-semibold text-sm">History</button>
                  </div>

                  {selectedPlanIds.length > 0 && (
                      <button onClick={startSelected} className="w-full py-3 mb-4 bg-green-600 hover:bg-green-700 rounded text-white font-bold animate-pulse">
                          Start Selected ({selectedPlanIds.length})
                      </button>
                  )}

                  <div className="flex-grow overflow-y-auto space-y-3 pr-1">
                      {plans.map((plan, index) => (
                          <PlanListItem 
                              key={plan.id}
                              plan={plan}
                              index={index}
                              onSelectPlan={handleEditPlan}
                              onInitiateDelete={deletePlan}
                              onInspectExercise={(name) => console.log('Inspect', name)}
                              onShowInfo={() => {}}
                              onShare={() => {}}
                              onTogglePin={() => {}} // Placeholder
                              isSelected={selectedPlanIds.includes(plan.id)}
                              onToggleSelection={toggleSelection}
                              isDraggable={!activeWorkout && !isSyncing}
                              onDragStart={handleDragStart}
                              onDragOver={handleDragOver}
                              onDrop={handleDrop}
                              onDragEnd={handleDragEnd}
                              onDragLeave={handleDragLeave}
                              isDragTarget={index === dragOverItemIndex}
                              isNewlyImported={plan.id === recentlyImportedPlanId}
                              setRef={(el) => { itemRefs.current[index] = el; }}
                          />
                      ))}
                      {plans.length === 0 && (
                          <div className="text-center text-gray-400 mt-10">
                              <p>No workout plans yet.</p>
                              <p className="text-sm mt-2">Create one to get started!</p>
                          </div>
                      )}
                  </div>
              </div>
          )}
      </div>
    </div>
  );
};

