import React, { useState, useRef, useEffect } from 'react';
import { useWorkout } from '../contexts/WorkoutContext';
import { useAuth } from '../contexts/AuthContext';
import { WorkoutPlan } from '../types';
import { WorkoutLog } from './WorkoutLog';
import { WorkoutInfoModal } from './WorkoutInfoModal';

interface WorkoutMenuProps {
  isOpen: boolean;
  setIsOpen: (isOpen: boolean) => void;
}

export const WorkoutMenu: React.FC<WorkoutMenuProps> = ({ isOpen, setIsOpen }) => {
  const { plans, startWorkout, activeWorkout, deletePlan, savePlan, workoutHistory, recentlyImportedPlanId } = useWorkout();
  const { user, signIn, signOut } = useAuth();

  const [selectedPlanIds, setSelectedPlanIds] = useState<string[]>([]);
  const [showLog, setShowLog] = useState(false);
  const [infoPlan, setInfoPlan] = useState<WorkoutPlan | null>(null);

  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleClose = () => {
    setIsOpen(false);
  };

  const handleMouseEnter = () => {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  };

  const handleMouseLeave = () => {
    if (isOpen) {
      closeTimerRef.current = setTimeout(() => {
        handleClose();
      }, 5000);
    }
  };

  useEffect(() => {
      if (!isOpen) {
          if (closeTimerRef.current) clearTimeout(closeTimerRef.current);
      }
  }, [isOpen]);

  const sortedPlans = [...plans].sort((a, b) => {
    if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;
    return (a.order || 0) - (b.order || 0);
  });

  const handleTogglePin = (plan: WorkoutPlan) => {
    savePlan({ ...plan, isPinned: !plan.isPinned });
  };

  const handleStart = () => {
    if (selectedPlanIds.length > 0) {
      startWorkout(selectedPlanIds);
      setIsOpen(false);
      setSelectedPlanIds([]);
    }
  };

  const togglePlanSelection = (id: string) => {
    setSelectedPlanIds(prev => prev.includes(id) ? prev.filter(p => p !== id) : [...prev, id]);
  };

  const handleSelectAll = () => {
      if (selectedPlanIds.length === plans.length) {
          setSelectedPlanIds([]);
      } else {
          setSelectedPlanIds(plans.map(p => p.id));
      }
  };

  const handleDelete = (planId: string, planName: string) => {
      if (window.confirm(`Are you sure you want to delete "${planName}"?`)) {
          deletePlan(planId);
          if (selectedPlanIds.includes(planId)) {
              togglePlanSelection(planId);
          }
      }
  };

  return (
    <>
      <div className="absolute top-4 left-4 menu-container group z-30">
        <button 
          onClick={() => isOpen ? handleClose() : setIsOpen(true)} 
          aria-label="Open workout menu"
          className="w-12 h-12 flex items-center justify-center rounded-full bg-gray-500/20 text-gray-400 hover:bg-gray-500/30 transition-opacity duration-1000 focus:outline-none opacity-0 group-hover:opacity-100"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
      </div>

      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40"
          onClick={handleClose}
        ></div>
      )}

      <div 
        className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-800/90 backdrop-blur-md shadow-2xl z-50 transform transition-all ease-in-out ${isOpen ? 'duration-500' : 'duration-[1500ms]'} ${isOpen ? 'translate-x-0 opacity-100' : '-translate-x-full opacity-0 pointer-events-none'}`}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className="flex flex-col h-full p-6">
          <div className="flex justify-between items-center mb-6 shrink-0">
             <h2 className="text-2xl font-bold text-white">Workouts</h2>
             <button onClick={handleClose} aria-label="Close workout menu" className="p-2 rounded-full hover:bg-gray-500/30 text-gray-400 hover:text-white">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
             </button>
          </div>

          <div className="flex-grow overflow-y-auto space-y-3 pr-2 scrollbar-thin scrollbar-thumb-gray-600">
             {plans.length === 0 ? (
                 <p className="text-gray-400 text-center mt-10">No workout plans yet.</p>
             ) : (
                 sortedPlans.map(plan => (
                    <div 
                        key={plan.id} 
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${selectedPlanIds.includes(plan.id) ? 'bg-blue-900/30 border-blue-500/50' : 'bg-gray-700/30 border-transparent hover:bg-gray-700/50'} ${recentlyImportedPlanId === plan.id ? 'ring-2 ring-green-500 animate-pulse' : ''}`}
                    >
                        <div 
                            className="flex items-center gap-3 overflow-hidden flex-grow cursor-pointer"
                            onClick={() => togglePlanSelection(plan.id)}
                        >
                            <div className={`w-5 h-5 rounded border flex items-center justify-center shrink-0 ${selectedPlanIds.includes(plan.id) ? 'bg-blue-500 border-blue-500' : 'border-gray-500'}`}>
                                {selectedPlanIds.includes(plan.id) && <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"/></svg>}
                            </div>
                            <div className="min-w-0">
                                <p className={`font-medium truncate ${selectedPlanIds.includes(plan.id) ? 'text-blue-200' : 'text-gray-200'}`}>{plan.name}</p>
                                <p className="text-xs text-gray-500">{plan.steps.filter(s => s.type === 'exercise').length} exercises • {Math.round(plan.steps.reduce((acc, s) => acc + (s.isRepBased ? 30 : s.duration), 0) / 60)} min</p>
                            </div>
                        </div>

                        <div className="flex items-center gap-1 shrink-0">
                             <button
                                onClick={(e) => { e.stopPropagation(); handleTogglePin(plan); }}
                                className={`p-2 hover:bg-gray-600/50 rounded-full transition-colors ${plan.isPinned ? 'text-blue-400' : 'text-gray-500 hover:text-gray-300'}`}
                                aria-label={plan.isPinned ? "Unpin plan" : "Pin plan"}
                                title={plan.isPinned ? "Unpin from top" : "Pin to top"}
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill={plan.isPinned ? "currentColor" : "none"} viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />
                                </svg>
                            </button>

                             <button
                                onClick={(e) => { e.stopPropagation(); setInfoPlan(plan); }}
                                className="p-2 text-gray-500 hover:text-gray-300 hover:bg-gray-600/50 rounded-full transition-colors"
                                aria-label="Plan info"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                </svg>
                            </button>

                            <button
                                onClick={(e) => { e.stopPropagation(); handleDelete(plan.id, plan.name); }}
                                className="p-2 text-gray-500 hover:text-red-400 hover:bg-gray-600/50 rounded-full transition-colors"
                                aria-label="Delete plan"
                                disabled={!!activeWorkout}
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                                </svg>
                            </button>
                        </div>
                    </div>
                 ))
             )}
          </div>

          <div className="mt-4 shrink-0 space-y-3">
             {plans.length > 0 && (
                 <div className="flex justify-between items-center text-sm text-gray-400 px-1">
                     <span>{selectedPlanIds.length} selected</span>
                     <button onClick={handleSelectAll} className="hover:text-white">
                         {selectedPlanIds.length === plans.length ? 'Deselect All' : 'Select All'}
                     </button>
                 </div>
             )}

             <button
                onClick={handleStart}
                disabled={selectedPlanIds.length === 0 || !!activeWorkout}
                className="w-full py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-700 disabled:text-gray-500 disabled:cursor-not-allowed text-white rounded-lg font-bold text-lg transition-colors shadow-lg"
             >
                {activeWorkout ? 'Workout in Progress' : 'Start Workout'}
             </button>

             <button
                onClick={() => setShowLog(true)}
                className="w-full py-2 bg-gray-700 hover:bg-gray-600 text-gray-200 rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
             >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                </svg>
                History & Logs
             </button>

             {user ? (
                 <div className="pt-2 border-t border-gray-700 flex justify-between items-center">
                     <div className="text-sm text-gray-400 truncate max-w-[150px]">
                         {user.email}
                     </div>
                     <button onClick={() => signOut()} className="text-sm text-red-400 hover:text-red-300">Sign Out</button>
                 </div>
             ) : (
                 <button onClick={() => signIn()} className="w-full py-2 border border-gray-600 hover:bg-gray-700 text-gray-300 rounded-lg text-sm transition-colors">
                     Sign in with Google
                 </button>
             )}
          </div>
        </div>
      </div>

      {infoPlan && <WorkoutInfoModal plan={infoPlan} onClose={() => setInfoPlan(null)} />}

      {showLog && (
        <div className="fixed inset-0 bg-gray-900 z-[100] overflow-auto animate-fadeIn">
            <div className="min-h-screen p-4">
                 <WorkoutLog onBack={() => setShowLog(false)} />
            </div>
        </div>
      )}
    </>
  );
};

