import React, { useState, useRef, useEffect } from 'react';
import { useWorkout } from '../contexts/WorkoutContext';
import { useAuth } from '../contexts/AuthContext';
import { WorkoutLog } from './WorkoutLog';
import { WorkoutPlan } from '../types';
import { generateWorkoutPlan } from '../services/geminiService';

export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void }> = ({ isOpen, setIsOpen }) => {
  const { 
    plans, 
    startWorkout, 
    deletePlan, 
    savePlan, 
    importPlan, 
    activeWorkout: contextActiveWorkout 
  } = useWorkout();
  const { user, signIn, signOut } = useAuth();

  const [activeTab, setActiveTab] = useState<'plans' | 'history' | 'ai'>('plans');
  const [isPinned, setIsPinned] = useState(false);
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // AI Planner State
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<{ role: 'user' | 'model'; parts: { text: string }[] }[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!isOpen && closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  }, [isOpen]);

  const handleClose = () => {
    setIsOpen(false);
    setIsPinned(false);
  };

  const handleMouseEnter = () => {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  };

  const handleMouseLeave = () => {
    if (isOpen && !isPinned) {
      closeTimerRef.current = setTimeout(() => {
        handleClose();
      }, 5000);
    }
  };

  const onTogglePin = (plan: WorkoutPlan) => {
    savePlan({ ...plan, isPinned: !plan.isPinned });
  };

  const handleStartWorkout = (planId: string) => {
    startWorkout([planId]);
    handleClose();
  };

  const handleDeletePlan = (planId: string, planName: string) => {
    if (window.confirm(`Are you sure you want to delete "${planName}"?`)) {
      deletePlan(planId);
    }
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        importPlan(json, 'file');
      } catch (err) {
        alert('Failed to parse JSON');
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim() || isGenerating) return;

    const userMsg = chatInput;
    setChatInput('');
    setIsGenerating(true);

    const newHistory = [...chatHistory, { role: 'user' as const, parts: [{ text: userMsg }] }];
    setChatHistory(newHistory);

    try {
        const responseText = await generateWorkoutPlan(newHistory, userMsg);

        // Check for JSON block to import
        const jsonMatch = responseText.match(/```json\n([\s\S]*?)\n```/);
        if (jsonMatch) {
             try {
                 const planData = JSON.parse(jsonMatch[1]);
                 importPlan(planData, 'ai');
             } catch (e) {
                 console.error("Failed to parse AI plan", e);
             }
        }

        setChatHistory(prev => [...prev, { role: 'model' as const, parts: [{ text: responseText }] }]);
    } catch (e) {
        setChatHistory(prev => [...prev, { role: 'model' as const, parts: [{ text: "Error connecting to AI." }] }]);
    } finally {
        setIsGenerating(false);
    }
  };

  const sortedPlans = [...plans].sort((a, b) => {
      if (a.isPinned && !b.isPinned) return -1;
      if (!a.isPinned && b.isPinned) return 1;
      return (a.order ?? 0) - (b.order ?? 0);
  });

  return (
    <>
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40"
          onClick={() => !isPinned && handleClose()}
        ></div>
      )}

      <div 
        className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-900/95 backdrop-blur-md shadow-2xl z-50 transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className="flex flex-col h-full p-4">
           {/* Header */}
           <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-white">Workouts</h2>
                <div className="flex items-center gap-2">
                     {user ? (
                         <button onClick={signOut} className="text-xs bg-red-900/50 text-red-200 px-2 py-1 rounded hover:bg-red-800">Sign Out</button>
                     ) : (
                         <button onClick={signIn} className="text-xs bg-blue-900/50 text-blue-200 px-2 py-1 rounded hover:bg-blue-800">Sign In</button>
                     )}
                     <button 
                        onClick={() => setIsPinned(!isPinned)}
                        className={`p-2 rounded-full hover:bg-gray-700 ${isPinned ? 'text-blue-400' : 'text-gray-400'}`}
                        title={isPinned ? "Unpin menu" : "Pin menu"}
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 3a1 1 0 01.707.293l3 3a1 1 0 01-1.414 1.414L10 5.414 7.707 7.707a1 1 0 01-1.414-1.414l3-3A1 1 0 0110 3zm-3.707 9.293a1 1 0 011.414 0L10 14.586l2.293-2.293a1 1 0 011.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" transform="rotate(45 10 10)" /></svg>
                    </button>
                    <button onClick={handleClose} className="p-2 rounded-full hover:bg-gray-700 text-gray-400" aria-label="Close menu">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                </div>
           </div>

           {/* Tabs */}
           <div className="flex border-b border-gray-700 mb-4">
                {['plans', 'history', 'ai'].map(tab => (
                    <button
                        key={tab}
                        onClick={() => setActiveTab(tab as any)}
                        className={`flex-1 py-2 text-center capitalize ${activeTab === tab ? 'text-blue-400 border-b-2 border-blue-400' : 'text-gray-400 hover:text-white'}`}
                    >
                        {tab === 'ai' ? 'AI Planner' : tab}
                    </button>
                ))}
           </div>

           {/* Content */}
           <div className="flex-1 overflow-y-auto">
               {activeTab === 'plans' && (
                   <div className="space-y-4">
                       <div className="flex gap-2">
                           <button onClick={handleImportClick} className="flex-1 bg-gray-800 hover:bg-gray-700 text-white py-2 rounded text-sm">Import JSON</button>
                           <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden" />
                       </div>

                       {sortedPlans.length === 0 ? (
                           <p className="text-gray-500 text-center mt-10">No plans found.</p>
                       ) : (
                           sortedPlans.map(plan => (
                               <div key={plan.id} className="bg-gray-800 rounded-lg p-4 flex items-center justify-between group">
                                   <div className="flex-1 min-w-0 mr-4">
                                       <h3 className="text-white font-semibold truncate">{plan.name}</h3>
                                       <p className="text-xs text-gray-400">{plan.steps.length} steps</p>
                                   </div>
                                   <div className="flex items-center gap-2">
                                       {/* Pin Button */}
                                       <button
                                          onClick={(e) => { e.stopPropagation(); onTogglePin(plan); }}
                                          className={`p-2 hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed ${plan.isPinned ? 'text-blue-400' : 'text-gray-500'}`}
                                          aria-label={plan.isPinned ? "Unpin plan" : "Pin plan"}
                                          title={plan.isPinned ? "Unpin from top" : "Pin to top"}
                                          disabled={!!contextActiveWorkout}
                                      >
                                          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                              <path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" />
                                          </svg>
                                      </button>
                                       <button 
                                            onClick={() => handleStartWorkout(plan.id)}
                                            disabled={!!contextActiveWorkout}
                                            className="bg-blue-600 hover:bg-blue-500 text-white p-2 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                                            title="Start Workout"
                                        >
                                           <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" /></svg>
                                       </button>
                                       <button 
                                            onClick={() => handleDeletePlan(plan.id, plan.name)}
                                            className="text-red-400 hover:text-red-300 p-2"
                                            title="Delete Plan"
                                        >
                                           <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" /></svg>
                                       </button>
                                   </div>
                               </div>
                           ))
                       )}
                   </div>
               )}

               {activeTab === 'history' && (
                   <div className="h-full">
                       <WorkoutLog onBack={() => setActiveTab('plans')} />
                   </div>
               )}

               {activeTab === 'ai' && (
                   <div className="flex flex-col h-full">
                       <div className="flex-1 overflow-y-auto space-y-4 mb-4">
                           {chatHistory.length === 0 && (
                               <div className="text-gray-500 text-center mt-10">
                                   <p>Describe your goal (e.g., "Full body workout 20 mins no equipment").</p>
                                   <p className="text-xs mt-2">I will generate a plan and import it for you.</p>
                               </div>
                           )}
                           {chatHistory.map((msg, idx) => (
                               <div key={idx} className={`p-3 rounded-lg ${msg.role === 'user' ? 'bg-blue-900/50 ml-8' : 'bg-gray-800 mr-8'}`}>
                                   <p className="text-sm text-gray-200 whitespace-pre-wrap">{msg.parts[0].text}</p>
                               </div>
                           ))}
                           {isGenerating && <p className="text-gray-400 text-xs animate-pulse">Generating...</p>}
                       </div>
                       <div className="flex gap-2">
                           <input 
                                type="text" 
                                className="flex-1 bg-gray-800 text-white rounded p-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                placeholder="Type a message..."
                                value={chatInput}
                                onChange={e => setChatInput(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                                disabled={isGenerating}
                           />
                           <button 
                                onClick={handleSendMessage}
                                disabled={isGenerating || !chatInput.trim()}
                                className="bg-blue-600 text-white p-2 rounded disabled:opacity-50"
                           >
                               Send
                           </button>
                       </div>
                   </div>
               )}
           </div>
        </div>
      </div>
    </>
  );
};

