import React, { useState, useEffect, useRef } from 'react';
import { useWorkout } from '../contexts/WorkoutContext';

interface WorkoutMenuProps {
  isOpen: boolean;
  setIsOpen: (isOpen: boolean) => void;
}

export const WorkoutMenu: React.FC<WorkoutMenuProps> = ({ isOpen, setIsOpen }) => {
  const { plans, startWorkout } = useWorkout();
  const [selectedPlanIds, setSelectedPlanIds] = useState<string[]>([]);
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleClose = () => {
    setIsOpen(false);
  };

  // Auto-close logic
  useEffect(() => {
    if (!isOpen && closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  }, [isOpen]);

  const handleMouseEnter = () => {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  };

  const handleMouseLeave = () => {
    if (isOpen) {
      closeTimerRef.current = setTimeout(() => {
        handleClose();
      }, 5000);
    }
  };

  const togglePlan = (id: string) => {
    setSelectedPlanIds(prev => 
      prev.includes(id) ? prev.filter(p => p !== id) : [...prev, id]
    );
  };

  const handleStart = () => {
    if (selectedPlanIds.length > 0) {
      startWorkout(selectedPlanIds);
      handleClose();
      setSelectedPlanIds([]);
    }
  };

  return (
    <>
      <div className="absolute top-4 left-4 menu-container group z-30">
        <button 
          onClick={() => isOpen ? handleClose() : setIsOpen(true)} 
          aria-label="Open workout menu"
          className="w-12 h-12 flex items-center justify-center rounded-full bg-gray-500/20 text-gray-400 hover:bg-gray-500/30 transition-opacity duration-1000 focus:outline-none opacity-0 group-hover:opacity-100"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
      </div>

      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40"
          onClick={handleClose}
        ></div>
      )}

      <div 
        className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-900/95 backdrop-blur-md shadow-2xl z-50 transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className="p-6 h-full flex flex-col">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-bold text-white">Workouts</h2>
            <button onClick={handleClose} className="text-gray-400 hover:text-white">
               <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>

          <div className="flex-grow overflow-y-auto space-y-2">
            {plans.length === 0 ? (
                <p className="text-gray-500 text-center mt-10">No workout plans found.</p>
            ) : (
                plans.map(plan => (
                    <div 
                        key={plan.id} 
                        onClick={() => togglePlan(plan.id)}
                        className={`p-3 rounded-lg border cursor-pointer transition-colors flex justify-between items-center ${selectedPlanIds.includes(plan.id) ? 'bg-blue-900/30 border-blue-500 text-white' : 'bg-gray-800/50 border-gray-700 text-gray-300 hover:bg-gray-800'}`}
                    >
                        <span className="font-medium">{plan.name}</span>
                        {selectedPlanIds.includes(plan.id) && <span className="text-blue-400">✓</span>}
                    </div>
                ))
            )}
          </div>

          <div className="mt-6">
            <button
                onClick={handleStart}
                disabled={selectedPlanIds.length === 0}
                className="w-full py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-700 disabled:text-gray-500 text-white rounded-lg font-bold transition-colors"
            >
                Start Selected ({selectedPlanIds.length})
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { useLogger } from '../contexts/LoggingContext';

const CRASH_FLAG_KEY = 'app_crash_detected';

interface Props {
  children?: ReactNode;
  logError: (error: Error, componentStack: string) => void;
}

interface State {
  hasError: boolean;
}

/**
 * Internal class-based ErrorBoundary to use lifecycle methods.
 * Fixed by extending Component directly and ensuring props/state are correctly typed.
 */
class ErrorBoundaryInternal extends Component<Props, State> {
  public state: State = {
    hasError: false
  };

  static getDerivedStateFromError(_: Error): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
    this.props.logError(error, errorInfo.componentStack || '');

    try {
        localStorage.setItem(CRASH_FLAG_KEY, 'true');
    } catch (e) {
        console.error("Could not set crash flag in localStorage:", e);
    }
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="h-screen w-screen bg-red-900 text-white flex flex-col items-center justify-center p-4 text-center">
            <h1 className="text-4xl font-bold">התרחשה שגיאה</h1>
            <p className="mt-4 text-lg">אפליקציית השעון נתקלה בבעיה בלתי צפויה.</p>
            <p className="mt-2 text-md text-red-200">
                נסה לרענן את הדף. אם הבעיה נמשכת, אנא פתח את תפריט ההגדרות, עבור לקטע 'מפתחים' והעתק את פרטי ניפוי השגיאות כדי לדווח על הבעיה.
            </p>
            <button
                onClick={() => window.location.reload()}
                className="mt-8 px-6 py-3 bg-red-600 rounded-lg font-semibold hover:bg-red-700 transition-colors"
            >
                רענן דף
            </button>
        </div>
      );
    }

    return this.props.children;
  }
}

/**
 * Functional wrapper for the ErrorBoundary to consume hooks.
 */
export const ErrorBoundary: React.FC<{children: ReactNode}> = ({ children }) => {
    const { logError } = useLogger();
    return <ErrorBoundaryInternal logError={logError}>{children}</ErrorBoundaryInternal>;
};
